import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['robot0_eye_in_hand','robot0_agentview_left'],include_depth=True,video='none');
for cam,pts in [('robot0_eye_in_hand',[(150,120),(160,120),(170,120),(160,140),(160,160),(180,150)]),('robot0_agentview_left',[(76,145),(80,145),(84,145),(80,150),(86,150)])]:
 K=np.array(o.meta['cameras'][cam]['intrinsic_cv']);T=np.array(o.meta['cameras'][cam]['cam2world_gl']);d=o.depth[cam][0];print(cam)
 for u,v in pts:
  z=float(d[v,u]);cc=np.array([(u-160)/K[0,0]*z,-(v-120)/K[1,1]*z,-z,1]);print((u,v),round(z,3),np.round((T@cc)[:3],3))
PY

